const fs = require('fs');
const path = require('path');

// Read and parse .env.test file
function loadEnvFile() {
  try {
    const envContent = fs.readFileSync('.env.test', 'utf8');
    const envVars = {};

    envContent.split('\n').forEach(line => {
      // Skip empty lines and comments
      if (line.trim() && !line.startsWith('#')) {
        const [key, value] = line.split('=', 2);
        if (key && value) {
          envVars[key.trim()] = value.trim();
        }
      }
    });

    return envVars;
  } catch (error) {
    if (error.code === 'ENOENT') {
      console.error('Error: .env.test file not found');
    } else {
      console.error('Error reading .env.test file:', error.message);
    }
    process.exit(1);
  }
}

// Load environment variables
const env = loadEnvFile();
const databaseUrl = env.DATABASE_URL;

if (!databaseUrl) {
  console.error('DATABASE_URL not found in .env.test');
  process.exit(1);
}

console.log(`Connected to database successfully: ${databaseUrl}`);

// Directory containing migration files
const migrationsDir = './migrations';

// Read all files from the migrations directory
fs.readdir(migrationsDir, (err, files) => {
  if (err) {
    if (err.code === 'ENOENT') {
      console.error(`Error: migrations directory not found at ${migrationsDir}`);
    } else {
      console.error(`Error reading directory ${migrationsDir}:`, err);
    }
    return;
  }

  // Filter only SQL files and sort them to apply in order
  const sqlFiles = files
    .filter(file => path.extname(file).toLowerCase() === '.sql')
    .sort();

  // Log each migration file that would be applied
  console.log('Applying migrations in order:');
  sqlFiles.forEach(file => {
    console.log(`- ${file}`);
  });
});

