// migrate.js
const fs = require('fs');
const path = require('path');

// Directory containing SQL migration files
class Migrator {
  constructor(migrationsDir = './migrations') {
    this.migrationsDir = path.resolve(migrationsDir);
  }

  // Read all SQL files from the migrations directory
  getMigrations() {
    try {
      const files = fs.readdirSync(this.migrationsDir);
      // Filter for .sql files and sort them lexicographically (typically by version/filename)
      return files
        .filter(file => path.extname(file).toLowerCase() === '.sql')
        .sort()
        .map(file => path.join(this.migrationsDir, file));
    } catch (err) {
      if (err.code === 'ENOENT') {
        console.error(`Migrations directory not found: ${this.migrationsDir}`);
      } else {
        console.error(`Error reading migrations directory: ${err.message}`);
      }
      return [];
    }
  }

  // Simulate applying migrations
  run() {
    const migrationFiles = this.getMigrations();

    if (migrationFiles.length === 0) {
      console.log('No migration files found.');
      return;
    }

    console.log('Applying migrations:');
    migrationFiles.forEach(file => {
      console.log(`- Applying ${path.basename(file)}...`);
      // In a real script, you'd apply the SQL file to the database here.
    });

    console.log('Migration complete.');
  }
}

// Run the migrator
if (require.main === module) {
  const migrator = new Migrator();
  migrator.run();
}

module.exports = Migrator;

